def round_half_to_even(n):
    """
    Round half to even.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 2 == 0:
        return n
    elif n % 2 == 1:
        return n + 1
    else:
        return n

def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass.
    """
    PointBase = type("PointBase", (object,), {"__slots__": fields})

    class Point(PointBase):
        """A point with the given fields and SRID map."""

        def __init__(self, *args, **kwargs):
            for i, attr in enumerate(fields):
                setattr(self, attr, args[i])
            for attr, value in kwargs.items():
                setattr(self, attr, value)

        def __repr__(self):
            return f"{name}({', '.join(getattr(self, attr) for attr in fields)})"

        def __eq__(self, other):
            return all(getattr(self, attr) == getattr(other, attr) for attr in fields)

        def __hash__(self):
            return hash(tuple(getattr(self, attr) for attr in fields))

        def __getitem__(self, attr):
            return getattr(self, attr)

        def __setitem__(self, attr, value):
            return setattr(self, attr, value)

        def __iter__(self):
            for attr in fields:
                yield getattr(self, attr)

        def __len__(self):
            return len(fields)

    Point.srid_map = srid_map
    return Point

