def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        yield cls
        for b in _all_dicts(cls.__bases__, seen):
            yield b

