def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    try:
        fixity = json.loads(fixity)
    except json.JSONDecodeError:
        raise ValueError("Fixity block is not valid JSON")

    if not isinstance(fixity, list):
        raise ValueError("Fixity block must be a list")

    for fixity_item in fixity:
        if len(fixity_item) != 2:
            raise ValueError("Fixity item must have 2 elements")

        filepath, checksums = fixity_item

        if not isinstance(filepath, str):
            raise ValueError("Filepath must be a string")

        if not isinstance(checksums, dict):
            raise ValueError("Checksums must be a dict")

        for name, checksum in checksums.items():
            if name not in ('md5', 'sha1', 'sha256'):
                raise ValueError("Invalid checksum algorithm: " + name)

            if not re.match(r'^[a-f0-9]{32}$', checksum):
                raise ValueError("Invalid checksum: " + checksum)

        if filepath not in manifest_files:
            raise ValueError("Filepath must be in the manifest")

