def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key, value = node
        if key in merged_nodes:
            if isinstance(value, MappingNode):
                merged_nodes[key] = deep_merge_nodes([
                    (child_key, child_value)
                    for child_key, child_value in value.value
                ])
            else:
                merged_nodes[key] = value
        else:
            merged_nodes[key] = value
    return [(key, value) for key, value in merged_nodes.items()]

def parse_subparser_arguments(unparsed_arguments, subparsers):
    result = {}
    remaining_arguments = []
    for argument in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            try:
                parsed_argument = subparser.parse_known_args(argument)
                result[subparser_name] = parsed_argument
                break
            except ArgumentError:
                pass
        else:
            remaining_arguments.append(argument)
    return (result, remaining_arguments)

def deep_merge_nodes(nodes):
    result = []
    for key, value in nodes:
        for i, (existing_key, existing_value) in enumerate(result):
            if key == existing_key:
                if isinstance(value, ruamel.yaml.nodes.MappingNode):
                    if isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                        result[i] = (key, deep_merge_nodes([existing_value, value]))
                    else:
                        raise ValueError("Failed to deep merge nodes: value types mismatch")
                break
        else:
            result.append((key, value))
    return result

