def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative:
        if not iface.providedBy(candidate):
            return False

    # Check that all required methods are defined and have the correct signature
    for name in iface.names():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid(
                f"{candidate} does not define method {name}"
            )
        method = getattr(candidate, name)
        if signature(method) != signature(getattr(iface, name)):
            raise zope.interface.Invalid(
                f"{candidate} method {name} has wrong signature"
            )

    # Check that all required attributes are defined
    for name in iface.names(lambda x: isinstance(x, zope.interface.Attribute)):
        if not hasattr(candidate.validate(), name):
            raise zope.interface.Invalid(
                f"{candidate} does not define attribute {name}"
            )

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate is a class
    if not inspect.isclass(candidate):
        return False

    # Check if the candidate has the required interface
    for attr in iface.__dict__:
        if not hasattr(candidate, attr):
            return False
        if not callable(getattr(candidate, attr)):
            return False

    # If tentative is True, do not check if the candidate has any additional methods
    if tentative:
        return True

    # Check if the candidate has any additional methods that are not in the interface
    for attr in candidate.__dict__:
        if not hasattr(iface, attr):
            return False

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclass = None
    if len(bases) == 1:
        # Single inheritance from a built-in type
        metaclass = type(bases[0])
    else:
        # Multiple inheritance or built-in type and other types
        metaclasses = {type(base) for base in bases} - {type(None)}
        metaclasses -= {type}
        if len(metaclasses) == 1:
            # Multiple inheritance with a single explicit metaclass
            metaclass = metaclasses.pop()
        elif explicit_mc is not None:
            # Multiple inheritance with an explicit metaclass
            metaclass = explicit_mc
        else:
            # Multiple inheritance with no explicit metaclass
            if type in metaclasses:
                # Metaclass compatibility will be checked later
                metaclasses |= {type}
            if len(metaclasses) == 1:
                # All bases agree on explicit metaclass
                metaclass = metaclasses.pop()
            else:
                # Incompatible metaclasses or multiple explicit metaclasses
                raise TypeError("Incompatible metaclasses in multiple inheritance: %s" %
                                 " ".join(metaclass.__name__ for metaclass in metaclasses))
    return metaclass

