def identify_request(request: RequestType):
    try:
        # Try to decode the request as a public XML payload
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    try:
        # Try to decode the request as a private encrypted JSON payload
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # If the request is not a recognized Diaspora payload, check if it is a legacy payload
    return is_legacy_payload(request)

