    for field in required_fields:
        if field not in data:
            raise IRValidatorException('Missing mandatory key in YAML file: {}'.format(field))

    if 'ingredients' in data:
        for ingredient in data['ingredients']:
            if 'quantity' not in ingredient or 'unit' not in ingredient or 'name' not in ingredient:
                raise IRValidatorException('Ingredient missing required fields: {}'.format(ingredient))
            if 'notes' in ingredient:
                for note in ingredient['notes']:
                    if note == 'optional':
                        continue
                    raise IRValidatorException('Invalid note in ingredient: {}'.format(note))
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if key == "include":
            for group, group_dict in value.items():
                parser_dict.setdefault(group, OrderedDict())
                for arg, arg_dict in group_dict.items():
                    parser_dict[group][arg] = arg_dict
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of resolved arguments and their values.
    """
    resolved_args = {}

    for arg in self.args:
        # If the argument is a subparser, resolve its defaults recursively
        if isinstance(arg, Subparser):
            resolved_args.update(arg.get_spec_defaults())

        # If the argument has a default value, add it to the resolved args
        if not isinstance(arg.default, NoDefault):
            resolved_args[arg.name] = arg.default

        # If the argument is a dictionary, resolve its default values recursively
        if isinstance(arg, DictOption):
            if arg.scheme:
                resolved_args[arg.name] = arg.scheme.get_spec_defaults()

    return resolved_args

def get_deprecated_args(self):
    """Returning dict with options which deprecate others.
    """
    return {
        "option1": {
            "deprecated_by": "option2",
            "to_be_removed_in_version": "1.0.0"
        },
        "option2": {
            "deprecated_by": "option3",
            "to_be_removed_in_version": "1.0.1"
        },
        "option3": {
            "deprecated_by": None,
            "to_be_removed_in_version": None
        }
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    # Check if there are any deprecated args
    deprecated_args = self.parsed_yaml.get('deprecated_args', {})

    # If there are deprecated args, check if they are present in the arg list
    if deprecated_args:
        for arg in deprecated_args:
            if arg in cli_args or arg in answer_file_args:
                warnings.warn(
                    "Deprecated argument '{}' will be removed in a future version.".format(arg),
                    category=DeprecationWarning,
                    stacklevel=2,
                )

    # Check if there are any new args that replace deprecated args
    arg_mappings = self.parsed_yaml.get('arg_mappings', {})
    for old_arg, new_arg in arg_mappings:
        if old_arg in cli_args or old_arg in answer_file_args:
            warnings.warn(
                "The '{old_arg}' argument has been deprecated and replaced with '{new_arg}'. '{old_arg}' will be removed in a future version.".format(
                    old_arg=old_arg, new_arg=new_arg
                ),
                category=DeprecationWarning,
                stacklevel=2,
            )

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    return self.parser.get_option_spec(command_name, argument_name)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.required_arguments:
        if arg not in args:
            raise ValueError(f"Missing required argument: {arg}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.max_length:
            raise ValueError(f"Argument '{arg}' exceeds maximum length of {self.max_length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg.arg_name in self.known_args:
            arg_value = arg.arg_value
            if arg_value not in self.known_args[arg.arg_name]:
                msg = "Invalid choice '{0}' for argument '{1}'.".format(arg_value, arg.arg_name)
                raise Exception(msg)

def validate_min_max_args(args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # check if minimum and maximum values are provided
    if 'min' not in args or 'max' not in args:
        raise ValueError("Minimum and maximum values must be provided")

    # check if minimum is less than maximum
    if args['min'] > args['max']:
        raise ValueError("Minimum value must be less than maximum value")

    # check if arguments are between minimum and maximum values
    for arg_name, arg_value in args.items():
        if arg_name == 'min' or arg_name == 'max':
            continue
        if arg_value < args['min'] or arg_value > args['max']:
            raise ValueError(f"Value of argument {arg_name} must be between minimum and maximum values")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key.replace('control_', '')] = value
        elif key.startswith('nested_'):
            nested_args[key.replace('nested_', '')] = value
        elif key.startswith('custom_'):
            custom_args[key.replace('custom_', '')] = value

    return control_args, nested_args, custom_args

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    workspace = ir_workspace.workspace
    plugin = ir_plugin.plugin
    if not playbook_path:
        raise ValueError("A playbook path is required.")
    if not os.path.isfile(playbook_path):
        raise ValueError("The playbook path does not exist.")
    if not os.path.isabs(playbook_path):
        playbook_path = os.path.join(workspace.base_dir, playbook_path)
    if verbose is None:
        verbose = ir_workspace.verbose
    if extra_vars is None:
        extra_vars = plugin.extra_vars
    if ansible_args is None:
        ansible_args = plugin.ansible_args
    command = ["ansible-playbook", playbook_path]
    if verbose:
        command.append("-" + "v" * verbose)
    if extra_vars:
        command.extend(["-e", json.dumps(extra_vars)])
    if ansible_args:
        command.extend(["-" + arg for arg in ansible_args])
    subprocess.run(command, check=True)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = load_plugin_spec(plugin_dir)
    flatten_dict = {}
    for prop_name, prop_value in plugin_spec.items():
        flatten_dict[prop_name] = prop_value
    return flatten_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get('CONFIG_PATH'):
        config_path = self.get_config_path()
        os.environ['CONFIG_PATH'] = config_path
        _log.info('Config path set to: %s', config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise Exception("Path does not start with root")
    return path[len(root):]
